# Reference p-values for Level 0's t distribution at large df (decision 90).
# Run with /usr/local/bin/Rscript make_p_large_df.R
# Writes p_large_df.csv next to this script: df,t,p with %.17g, where p is
# 2 * pt(|t|, df, lower.tail = FALSE). The grid is the Phase 4 evaluation's
# section 5 grid: 13 df from 1e3 to 1e7 and 14 values of |t| from 0.5 to 10.
args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))
dfs <- c(1e3, 2e3, 5e3, 1e4, 2e4, 5e4, 1e5, 2e5, 5e5, 1e6, 2e6, 5e6, 1e7)
ts <- c(0.5, 1, 1.5, 1.96, 2, 2.5, 3, 3.5, 4, 5, 6, 7, 8, 10)
rows <- expand.grid(df = dfs, t = ts)
rows$p <- 2 * pt(abs(rows$t), rows$df, lower.tail = FALSE)
f17 <- function(x) sprintf("%.17g", x)
out <- file.path(here, "p_large_df.csv")
writeLines(c(
  "# Reference two-tailed t p-values at large df for gaply_core's Level 0 (decision 90).",
  "# Generated by /usr/local/bin/Rscript make_p_large_df.R (do not edit by hand).",
  sprintf("# %s, %s.", R.version.string, R.version$arch),
  "# p = 2 * pt(|t|, df, lower.tail = FALSE). Numbers are %.17g."), out)
write.table(data.frame(df = f17(rows$df), t = f17(rows$t), p = f17(rows$p)), out, sep = ",",
            quote = FALSE, row.names = FALSE, append = TRUE)
cat(sprintf("wrote %d rows\n", nrow(rows)))
